Lemma accok_write_gen : forall live frames (m : mem) x bs a n (k : Z),
  Z.of_nat (length bs) = k -> 0 <= x -> x + k <= 2^64 -> 0 <= n ->
  accok live frames m a n -> (x + k <= shad a \/ shad (a + n) + 1 <= x) ->
  accok live frames (write_to_mem m (wa x) bs) a n.
